2021-06-30Explanation: This example demonstrates optional parsing sections. The formatter accepts input in multiple formats (yyyy, yyyyMM, and yyyyMMdd). Missing month and day values are automatically assigned default values using parseDefaulting().Example 3: Java Program to illustrate DateTimeFormatterBuilder Class
            Java

    // Importing required classes
import java.io.*;
import java.lang.*;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.TextStyle;
import java.time.temporal.ChronoField;
import java.util.Locale;

// Main class
// DateTimeFormatterBuilderExample
class GFG {

    // Main driver method
    public static void main(String[] args)
    {
        // Creating object of LocalDate class
        // inside main() method
        LocalDate date = LocalDate.of(2021, 6, 30);

        // Creating object of DateTimeFormatter class

        // Object 1
        DateTimeFormatter formatter
            = DateTimeFormatter.ofPattern("dd/MM/yyyy");

        // Object 2
        DateTimeFormatter italianFormatter
            = DateTimeFormatter.ofPattern("d. MMMM yyyy",
                                          Locale.ITALIAN);

        // Print and display date in format XX-XX-XX
        System.out.println(
            date.format(DateTimeFormatter.ISO_LOCAL_DATE));

        // Print and display date in format XX/XX/XX
        System.out.println(date.format(formatter));

        // Print and display Italian date formatter
        System.out.println(date.format(italianFormatter));

        // Object 3
        DateTimeFormatter complexFormatter
            = new DateTimeFormatterBuilder()
                  .appendText(ChronoField.DAY_OF_MONTH)
                  .appendLiteral(". ")
                  .appendText(ChronoField.MONTH_OF_YEAR)
                  .appendLiteral(" ")
                  .appendText(ChronoField.YEAR)
                  .parseCaseInsensitive()
                  .toFormatter(Locale.US);

        // Print and display US date formatter
        System.out.println(date.format(complexFormatter));
    }
}

